const insertOutboxEvent = `-- name: InsertOutboxEvent :one
INSERT INTO outbox_events (
    aggregate_id,
    event_type,
    kafka_topic,
    payload_proto,
    status,
    retry_count
) VALUES (
    $1, $2, $3, $4, 'pending', 0
)
RETURNING id, aggregate_id, event_type, kafka_topic, payload_proto, status, created_at, published_at, retry_count, last_error
`

type InsertOutboxEventParams struct {
	AggregateID  string `json:"aggregate_id"`
	EventType    string `json:"event_type"`
	KafkaTopic   string `json:"kafka_topic"`
	PayloadProto []byte `json:"payload_proto"`
}

// Inserts a pending message for Kafka delivery.
// Part 2 of the Transactional Outbox. Must be run in the same db.Tx as InsertWebhookPayload.
func (q *Queries) InsertOutboxEvent(ctx context.Context, arg InsertOutboxEventParams) (OutboxEvent, error) {
	row := q.db.QueryRow(ctx, insertOutboxEvent,
		arg.AggregateID,
		arg.EventType,
		arg.KafkaTopic,
		arg.PayloadProto,
	)
	var i OutboxEvent
	err := row.Scan(
		&i.ID,
		&i.AggregateID,
		&i.EventType,
		&i.KafkaTopic,
		&i.PayloadProto,
		&i.Status,
		&i.CreatedAt,
		&i.PublishedAt,
		&i.RetryCount,
		&i.LastError,
	)
	return i, err
}

const insertWebhookPayload = `-- name: InsertWebhookPayload :one

INSERT INTO webhook_payloads (
    delivery_id,
    event_type,
    action,
    installation_id,
    organization_id,
    repository_id,
    sender_login,
    payload,
    signature_valid
) VALUES (
    $1, $2, $3, $4, $5, $6, $7, $8, $9
)
RETURNING id, delivery_id, event_type, action, installation_id, organization_id, repository_id, sender_login, payload, signature_valid, received_at, processed_at
`

type InsertWebhookPayloadParams struct {
	DeliveryID     pgtype.UUID `json:"delivery_id"`
	EventType      string      `json:"event_type"`
	Action         pgtype.Text `json:"action"`
	InstallationID int64       `json:"installation_id"`
	OrganizationID pgtype.Int8 `json:"organization_id"`
	RepositoryID   pgtype.Int8 `json:"repository_id"`
	SenderLogin    pgtype.Text `json:"sender_login"`
	Payload        []byte      `json:"payload"`
	SignatureValid bool        `json:"signature_valid"`
}

// =============================================================================
// Sentra API Gateway — sqlc Queries
// =============================================================================
// These raw SQL queries are compiled by sqlc into type-safe Go functions.
// We use this for the hot webhook ingestion path where ORM overhead is unacceptable.
// =============================================================================
// Inserts the raw GitHub webhook payload into the immutable audit log.
// Part 1 of the Transactional Outbox.
func (q *Queries) InsertWebhookPayload(ctx context.Context, arg InsertWebhookPayloadParams) (WebhookPayload, error) {
	row := q.db.QueryRow(ctx, insertWebhookPayload,
		arg.DeliveryID,
		arg.EventType,
		arg.Action,
		arg.InstallationID,
		arg.OrganizationID,
		arg.RepositoryID,
		arg.SenderLogin,
		arg.Payload,
		arg.SignatureValid,
	)
	var i WebhookPayload
	err := row.Scan(
		&i.ID,
		&i.DeliveryID,
		&i.EventType,
		&i.Action,
		&i.InstallationID,
		&i.OrganizationID,
		&i.RepositoryID,
		&i.SenderLogin,
		&i.Payload,
		&i.SignatureValid,
		&i.ReceivedAt,
		&i.ProcessedAt,
	)
	return i, err
}

