const upsertUser = `-- name: UpsertUser :one

INSERT INTO users (
    github_id,
    login,
    name,
    email,
    avatar_url,
    github_access_token,
    installation_id,
    updated_at
) VALUES (
    $1, $2, $3, $4, $5, $6, $7, NOW()
)
ON CONFLICT (github_id) DO UPDATE
SET
    login               = EXCLUDED.login,
    name                = EXCLUDED.name,
    email               = EXCLUDED.email,
    avatar_url          = EXCLUDED.avatar_url,
    github_access_token = EXCLUDED.github_access_token,
    installation_id     = COALESCE(EXCLUDED.installation_id, users.installation_id),
    updated_at          = NOW()
RETURNING id, github_id, login, name, email, avatar_url, github_access_token, installation_id, current_org_id, created_at, updated_at
`

type UpsertUserParams struct {
	GithubID          int64       `json:"github_id"`
	Login             string      `json:"login"`
	Name              pgtype.Text `json:"name"`
	Email             pgtype.Text `json:"email"`
	AvatarUrl         pgtype.Text `json:"avatar_url"`
	GithubAccessToken pgtype.Text `json:"github_access_token"`
	InstallationID    pgtype.Int8 `json:"installation_id"`
}

// =============================================================================
// User Authentication Queries (Phase 11: GitHub OAuth)
// =============================================================================
// Creates or updates a user based on their GitHub ID (upsert on conflict).
// Returns the full user row after insert/update.
func (q *Queries) UpsertUser(ctx context.Context, arg UpsertUserParams) (User, error) {
	row := q.db.QueryRow(ctx, upsertUser,
		arg.GithubID,
		arg.Login,
		arg.Name,
		arg.Email,
		arg.AvatarUrl,
		arg.GithubAccessToken,
		arg.InstallationID,
	)
	var i User
	err := row.Scan(
		&i.ID,
		&i.GithubID,
		&i.Login,
		&i.Name,
		&i.Email,
		&i.AvatarUrl,
		&i.GithubAccessToken,
		&i.InstallationID,
		&i.CurrentOrgID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
